param([Parameter(Mandatory=$true)][string]$GameDataPath,[string]$SourceRoot,[switch]$Portable,[ValidateSet('Config','Windowed','Fullscreen','Borderless')][string]$DisplayMode='Borderless',[ValidateRange(-1,15)][int]$Monitor=-1,[ValidateRange(-1,8)][int]$VSync=1,[ValidateRange(0,1000)][int]$MaxRefresh=0)
. (Join-Path $PSScriptRoot 'common.ps1')
if(-not $SourceRoot){$SourceRoot=Get-SourceRoot};$exe=Join-Path $SourceRoot 'sw.exe';if(-not(Test-Path $exe)){throw "sw.exe was not found at $exe. Build the port first."};$data=(Resolve-Path $GameDataPath -ErrorAction Stop).Path;$grp=Join-Path $data 'SW.GRP';if(-not(Test-Path $grp)){throw "SW.GRP was not found in $data."}
$marker=Join-Path $SourceRoot 'user_profiles_disabled';if($Portable){if(-not(Test-Path $marker)){New-Item -ItemType File -Path $marker|Out-Null}}elseif(Test-Path $marker){Remove-Item $marker -Force}
$names=@('SWGRP','SW_DISPLAY_MODE','SW_MONITOR','SW_VSYNC','SW_MAX_REFRESH');$old=@{};foreach($name in $names){$old[$name]=[Environment]::GetEnvironmentVariable($name,'Process')};$env:SWGRP=$grp;if($DisplayMode -eq 'Config'){Remove-Item Env:SW_DISPLAY_MODE -ErrorAction SilentlyContinue}else{$env:SW_DISPLAY_MODE=$DisplayMode.ToLowerInvariant()};if($Monitor -ge 0){$env:SW_MONITOR=[string]$Monitor}else{Remove-Item Env:SW_MONITOR -ErrorAction SilentlyContinue};$env:SW_VSYNC=[string]$VSync;if($MaxRefresh -gt 0){$env:SW_MAX_REFRESH=[string]$MaxRefresh}else{Remove-Item Env:SW_MAX_REFRESH -ErrorAction SilentlyContinue}
Push-Location $SourceRoot
try{& $exe;if($LASTEXITCODE -ne 0){throw "Shadow Warrior exited with code $LASTEXITCODE."}}finally{Pop-Location;foreach($name in $names){if($null -eq $old[$name]){Remove-Item ('Env:'+$name) -ErrorAction SilentlyContinue}else{[Environment]::SetEnvironmentVariable($name,$old[$name],'Process')}}}
